"use client";

import { forwardRef, useId, type SelectHTMLAttributes } from "react";
import { controlStyles, controlBorder, controlError, labelStyles } from "@/lib/brasa/utils/styles";

export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
}
export interface SelectProps extends SelectHTMLAttributes<HTMLSelectElement> {
  label?: string;
  error?: string;
  options: SelectOption[];
  placeholder?: string;
}

export const Select = forwardRef<HTMLSelectElement, SelectProps>(
  ({ className = "", label, error, options, placeholder, id, "aria-describedby": describedBy, ...props }, ref) => {
    const generatedId = useId();
    const selectId = id ?? generatedId;
    return (
      <div className="space-y-1.5">
        {label && <label htmlFor={selectId} className={labelStyles}>{label}</label>}
        <div className="relative">
          <select
            ref={ref}
            {...props}
            id={selectId}
            aria-invalid={error ? true : props["aria-invalid"]}
            aria-describedby={[describedBy, error ? `${selectId}-error` : undefined].filter(Boolean).join(" ") || undefined}
            className={`${controlStyles} appearance-none pr-9 ${error ? controlError : controlBorder} ${className}`}
          >
            {placeholder && <option value="" disabled>{placeholder}</option>}
            {options.map((option) => <option key={option.value} value={option.value} disabled={option.disabled}>{option.label}</option>)}
          </select>
          <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" className="pointer-events-none absolute right-3 top-3 size-4 text-[#6b766d]"><path d="m8 10 4 4 4-4" /></svg>
        </div>
        {error && <p id={`${selectId}-error`} className="text-xs text-red-700" role="alert">{error}</p>}
      </div>
    );
  }
);
Select.displayName = "Select";

/** Shared visual language. Fallbacks also work in copied components. */
export const controlStyles = "flex h-10 w-full min-w-0 rounded-[var(--brasa-radius-control,0.625rem)] border bg-[var(--brasa-surface,#fff)] px-3 py-2 text-sm text-[var(--brasa-foreground,#23352c)] shadow-[0_1px_2px_#182a1e05] transition-[border-color,box-shadow,background-color] duration-150 placeholder:text-[#8a938c] focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-[var(--brasa-ring,#dce9df)] disabled:cursor-not-allowed disabled:bg-[#f5f6f2] disabled:opacity-60 motion-reduce:transition-none";
export const controlBorder = "border-[var(--brasa-border,#dfe4dc)] hover:border-[#b7c3b8] focus-visible:border-[var(--brasa-primary,#285b43)]";
export const controlError = "border-red-400 focus-visible:border-red-500 focus-visible:ring-red-100";
export const labelStyles = "block text-[13px] font-medium leading-5 text-[var(--brasa-foreground,#23352c)]";
export const surfaceStyles = "rounded-[var(--brasa-radius-card,1rem)] border border-[var(--brasa-border,#dfe4dc)] bg-[var(--brasa-surface,#fff)] text-[var(--brasa-foreground,#23352c)]";
export const focusStyles = "focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-[var(--brasa-ring,#dce9df)] focus-visible:ring-offset-2 motion-reduce:transition-none";
